    // Random numbers
    final UniformRandomProvider rng = RandomSource.create(RandomSource.SPLIT_MIX_64);
    for (int i = 0; i < 100; i++) {
        final double x = next(rng);
        final double y = next(rng);
        assertFunctionType(complex(x, y), operation, type, UnspecifiedSign.NONE);
    }
}

